style.css:
@-moz-document domain("discord.com") {
:root {
        background: url("https://i.postimg.cc/1tMZxR9p/Screenshot-2025-02-02-01-45-17.pngabsolute") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Maak Discord vensters semi-transparant */
    .theme-dark, .theme-light {
        --background-primary: rgba(0, 0, 0, 0.6) !important;
        --background-secondary: rgba(20, 20, 20, 0.6) !important;
        --background-tertiary: rgba(40, 40, 40, 0.6) !important;
    }

    /* Maak de zijbalk transparant */
    .sidebar-1tnWFu {
        background: rgba(0, 0, 0, 0.5) !important;
    }

    /* Verwijder eventuele overlays die de achtergrond blokkeren */
    .appMount-3lHmkl {
        background: transparent !important;
    }
}
